def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = []
    for word in words:
        letters = sorted(c for c in word if c.isalnum())
        non_letters = [c for c in word if not c.isalnum()]
        sorted_word = ''
        letter_index = 0
        for c in word:
            if c.isalnum():
                sorted_word += letters[letter_index]
                letter_index += 1
            else:
                sorted_word += c
        sorted_words.append(sorted_word)
    return ' '.join(sorted_words)

def next_smallest(lst):
    unique_elements = set(lst)
    if len(unique_elements) < 2:
        return None
    return sorted(unique_elements)[1]

def max_fill(grid, capacity):
    total_water = sum(sum(row) for row in grid)
    return (total_water + capacity - 1) // capacity

def minPath(grid, k):
    from collections import deque
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_path = None
    queue = deque()

    # Start BFS from all cells
    for i in range(N):
        for j in range(N):
            queue.append((i, j, [grid[i][j]]))  # (row, col, path)

    while queue:
        r, c, path = queue.popleft()

        if len(path) == k:
            # Check if we found a new minimum path
            if min_path is None or path < min_path:
                min_path = path
            continue

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                queue.append((nr, nc, path + [grid[nr][nc]]))

    return min_path

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    return n >= 8 and n % 2 == 0

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))
    return [num for _, num in sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0]))]

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    return x if is_prime(n) else y

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
